css:
.nav {
  display: flex;
  gap: 32px;
  padding: 32px;
  font-family: system-ui, sans-serif;
  font-size: 18px;
}

.link {
  position: relative;
  padding-bottom: 4px;
  color: #18181b;
  text-decoration: none;
}

.link::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 2px;
  background-color: #f97316;
  transform: scaleX(0);
  transition: transform 250ms ease;
}

.link:hover::after,
.link:focus-visible::after {
  transform: scaleX(1);
}

.from-left::after {
  transform-origin: left;
}

.from-center::after {
  transform-origin: center;
}

.from-right::after {
  transform-origin: right;
}
